  {billing&&<Modal title={passActive?'Your Pro plan':'Pro subscription'} onClose={()=>setBilling(false)}><div className="billing-art"><Icon name="spark" size={32}/></div><p className="modal-lead">Professional, unbranded PDF exports.</p>{passActive?<div className="pass-active"><Icon name="check"/><strong>Pro is active</strong><p>{access.cancelAtPeriodEnd?'Your plan ends on':'Next billing date:'} {new Date(access.expiresAt!).toLocaleDateString()}.</p><button className="btn secondary" disabled={busy} onClick={()=>void manageBilling()}>Manage or cancel subscription<Icon name="external" size={15}/></button></div>:<><div className="price">$5 <span>USD / month</span></div><ul className="benefits"><li><Icon name="check" size={17}/>Unlimited PDF exports without our branding</li><li><Icon name="check" size={17}/>Up to 2,000 saved invoices and quotes</li><li><Icon name="check" size={17}/>All three invoice templates and four brand colors</li><li><Icon name="check" size={17}/>Monthly subscription. Cancel at any time.</li></ul><p className="fine-print">$5 USD is charged each month until you cancel. Sign in to the same account on any device to restore access. Your free workspace includes 10 saved documents. Pro supports up to 2,000 saved documents within the workspace storage limit. Client payments are recorded manually.</p>{access.testMode&&<div className="warning">Stripe is in test mode. No real payment will be taken.</div>}<button className="btn primary full-width" disabled={busy||!!userId&&!access.configured} onClick={()=>userId?void checkout():location.assign('/login')}><Icon name="lock" size={17}/>{busy?'Opening secure checkout…':!userId?'Sign in to get a Pro subscription':access.configured?'Subscribe to Pro — $5/month':'Checkout temporarily unavailable'}</button></>}{!passActive&&access.portalAvailable&&<button className="btn secondary full-width" disabled={busy} onClick={()=>void manageBilling()}>Manage billing or update payment method</button>}<button className="btn plain full-width" disabled={busy} onClick={()=>void restore()}>Already paid? Restore account access</button><p className="fine-print center">Payments handled securely by Stripe.</p></Modal>}
  {help&&<Modal title="Help & documentation." onClose={()=>setHelp(false)}><div className="guidance"><h3>1. Make it yours</h3><p>Add your business details in Settings. They become the defaults for new invoices.</p><h3>2. Create, save, export</h3><p>Choose a client, add your work and pick a template. Save your invoice to the dashboard, then download its PDF.</p><h3>3. Keep an honest record</h3><p>Mark invoices as sent or paid yourself. These labels track your records; they do not send email or confirm a bank payment.</p><h3>4. Back up your workspace</h3><p>Download a backup in Settings regularly. Your account synchronizes saved documents. Backups give you an independent copy. Editing drafts stay on the current device.</p><h3>Need help?</h3><p><a href="mailto:getpaidfast-app-support@googlegroups.com">Contact GetPaidFast support</a> for account or subscription questions.</p></div></Modal>}
  {service&&<Modal title={workspace.services?.some(s=>s.id===service.id)?'Edit service':'New service'} onClose={()=>setService(null)}><form className="form-stack" onSubmit={e=>{e.preventDefault();if(!service.name.trim()||!Number.isFinite(service.rate)||service.rate<0||service.rate>100000000)return;saveWorkspace({...workspace,services:workspace.services?.some(s=>s.id===service.id)?workspace.services.map(s=>s.id===service.id?service:s):[...(workspace.services||[]),service]});setService(null);notify('Service saved to your catalog.');}}><Field label="Service / product name"><input autoFocus required maxLength={200} value={service.name} onChange={e=>setService({...service,name:e.target.value})}/></Field><div className="form-grid"><Field label="Rate"><input required type="number" min="0" max="100000000" step="0.01" value={service.rate} onChange={e=>setService({...service,rate:Number(e.target.value)})}/></Field><Field label="Currency"><select value={service.currency} onChange={e=>setService({...service,currency:e.target.value as Currency})}>{CURRENCIES.map(c=><option key={c}>{c}</option>)}</select></Field></div><button className="btn primary" type="submit">Save service<Icon name="check" size={16}/></button></form></Modal>}
